def get_crypto_prices():
    # Import necessary libraries
    import requests
    # Define the API URLs
    api_urls = {'ethereum': 'https://api.example.com/ethereum/price', 'dogecoin': 'https://api.example.com/dogecoin/price'}
    # Make the API calls
    responses = {coin: requests.get(api_url) for coin, api_url in api_urls.items()}
    # Check if the responses were successful
    if all(response.status_code == 200 for response in responses.values()):
        # Return the prices as a dictionary
        return {coin: float(response.json()['price']) for coin, response in responses.items()}
    else:
        # Handle the error
        return None

def test_get_crypto_prices():
    # Test the function with different API calls
    for _ in range(5):
        print(get_crypto_prices())

